  const dx = dragStart.x - dragNow.x;
  const dy = dragStart.y - dragNow.y;
  const pull = Math.min(Math.hypot(dx, dy), 120);
  const angle = Math.atan2(dy, dx);

  const endX = ball.x + Math.cos(angle) * pull;
  const endY = ball.y + Math.sin(angle) * pull;

  ctx.strokeStyle = "#ffffffdd";
  ctx.lineWidth = 5;
  ctx.setLineDash([9, 8]);
  ctx.beginPath();
  ctx.moveTo(ball.x, ball.y);
  ctx.lineTo(endX, endY);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = "#ffffff33";
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, pull, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#213020";
  ctx.font = "700 16px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("Release to putt", ball.x, Math.max(28, ball.y - 32));
}

function loop() {
  windmill.angle += windmill.speed;

  drawCourse();
  drawWindmill();
  bladeCollision();
  updateBall();
  drawAim();
  drawBall();

  requestAnimationFrame(loop);
}

