  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = "#3c8b43";
  ctx.lineWidth = 34;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(75, 250);
  ctx.lineTo(685, 250);
  ctx.stroke();

  ctx.fillStyle = "#4ca653";
  ctx.beginPath();
  ctx.arc(150, 128, 48, 0, Math.PI * 2);
  ctx.arc(600, 380, 55, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#213020";
  ctx.beginPath();
  ctx.arc(hole.x, hole.y, hole.r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#f7f1d1";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(hole.x, hole.y, hole.r + 7, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = "#b57634";
  ctx.fillRect(windmill.x - 34, windmill.y - 55, 68, 110);

  ctx.fillStyle = "#f6d28a";
  ctx.beginPath();
  ctx.moveTo(windmill.x - 48, windmill.y - 55);
  ctx.lineTo(windmill.x, windmill.y - 105);
  ctx.lineTo(windmill.x + 48, windmill.y - 55);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = "#8d5d2a";
