  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(ball.x, ball.y);
  ctx.lineTo(endX, endY);
  ctx.stroke();

  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(endX, endY, 8, 0, Math.PI * 2);
  ctx.fill();

  const meterX = 24;
  const meterY = 28;
  const meterW = 190;
  const meterH = 18;

  ctx.fillStyle = "#18331fdd";
  ctx.fillRect(meterX, meterY, meterW, meterH);

  ctx.fillStyle = powerPct < 0.45 ? "#dfffa1" : powerPct < 0.75 ? "#ffe082" : "#ff8b73";
  ctx.fillRect(meterX, meterY, meterW * powerPct, meterH);

  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 2;
  ctx.strokeRect(meterX, meterY, meterW, meterH);

  ctx.fillStyle = "#ffffff";
  ctx.font = "800 15px system-ui, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("POWER", meterX, meterY + 36);
}

function drawHitFeedback() {
  if (hitFlash <= 0) return;

  const alpha = hitFlash / 18;

  ctx.fillStyle = `rgba(255, 75, 55, ${0.18 * alpha})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, 24 + (18 - hitFlash) * 3, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
  ctx.font = "900 34px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("BLADE HIT!", canvas.width / 2, 86);
}

function loop() {
  windmill.angle += windmill.speed;

  const sx = shake > 0 ? (Math.random() - 0.5) * shake : 0;
  const sy = shake > 0 ? (Math.random() - 0.5) * shake : 0;

  ctx.save();
  ctx.translate(sx, sy);

  drawCourse();
  drawWindmill();
  bladeCollision();
  updateBall();
  drawAim();
  drawBall();
  drawHitFeedback();

  ctx.restore();

  if (hitFlash > 0) hitFlash--;
  if (shake > 0) shake *= 0.82;

  requestAnimationFrame(loop);
}

resetGame();
loop();
