    .hud {
      grid-template-columns: 1fr 1fr;
      gap: 6px;
    }

    .pill {
      padding: 8px 6px;
      font-size: 13px;
    }

    #status {
      grid-column: 1 / -1;
    }

    canvas {
      border-width: 3px;
      border-radius: 13px;
    }

    .scorecard {
      inset: 6px;
      padding: 8px;
      border-radius: 11px;
    }

    .card {
      padding: 13px;
      border-width: 3px;
    }

    button {
      width: 100%;
      padding: 14px 18px;
      font-size: 16px;
    }
  }
</style>
</head>
<body>
<div class="wrap">
  <h1>Tiny Windmill Mini Golf</h1>
  <p class="instructions">Drag from the ball to aim. Shape it around the bumper, then time the blade. Par 3.</p>

  <div class="hud">
    <div class="pill">Strokes: <span id="strokes">0</span></div>
    <div class="pill">Par: 3</div>
    <div class="pill" id="status">Ready</div>
  </div>

  <div class="gameBox">
    <canvas id="game" width="760" height="500"></canvas>

    <div class="scorecard" id="scorecard">
      <div class="card">
        <h2 id="scoreTitle">Par</h2>
        <div class="result" id="scoreResult">Finished even with par.</div>
        <div class="scoreRow"><span>Hole</span><span>Windmill</span></div>
        <div class="scoreRow"><span>Par</span><span>3</span></div>
        <div class="scoreRow"><span>Your score</span><span id="finalStrokes">3</span></div>
        <button onclick="resetGame()">Play Again</button>
      </div>
    </div>
  </div>

  <button onclick="resetGame()">Reset Hole</button>
</div>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const strokesEl = document.getElementById("strokes");
const statusEl = document.getElementById("status");
const scorecardEl = document.getElementById("scorecard");
const scoreTitleEl = document.getElementById("scoreTitle");
const scoreResultEl = document.getElementById("scoreResult");
const finalStrokesEl = document.getElementById("finalStrokes");

const PAR = 3;
const ballStart = { x: 95, y: 250 };
const hole = { x: 680, y: 250, r: 18 };
const windmill = { x: 390, y: 250, r: 92, angle: 0, speed: 0.035 };
const bumpers = [{ x: 300, y: 185, r: 42 }, { x: 300, y: 315, r: 42 }];

let ball, strokes, dragging, dragStart, dragNow, won;
let hitFlash = 0;
let shake = 0;

function resetGame() {
  ball = { x: ballStart.x, y: ballStart.y, vx: 0, vy: 0, r: 9 };
  strokes = 0;
  dragging = false;
  dragStart = null;
  dragNow = null;
  won = false;
  hitFlash = 0;
  shake = 0;
  strokesEl.textContent = strokes;
  scorecardEl.classList.remove("show");
  setStatus("Ready");
}

function setStatus(text, hit = false) {
  statusEl.textContent = text;
  statusEl.classList.toggle("hit", hit);
}

function showScorecard() {
  let title = "Par";
  let result = "Finished even with par.";

  if (strokes === 1) {
    title = "Hole in One!";
    result = "Ace. Two under par.";
  } else if (strokes === 2) {
    title = "Birdie";
    result = "Finished one under par.";
  } else if (strokes === 4) {
    title = "Bogey";
    result = "One over par.";
  } else if (strokes > 4) {
    title = "Double Bogey+";
    result = `${strokes - PAR} over par.`;
  }

  scoreTitleEl.textContent = title;
  scoreResultEl.textContent = result;
  finalStrokesEl.textContent = strokes;
  scorecardEl.classList.add("show");
}

function pointerPos(e) {
  const rect = canvas.getBoundingClientRect();
  return {
    x: (e.clientX - rect.left) * canvas.width / rect.width,
    y: (e.clientY - rect.top) * canvas.height / rect.height
  };
}

function ballSpeed() {
  return Math.hypot(ball.vx, ball.vy);
}

function ballStopped() {
  return ballSpeed() < 0.08;
}

function stopScroll(e) {
  e.preventDefault();
}

canvas.addEventListener("pointerdown", e => {
  stopScroll(e);
  if (won || !ballStopped()) return;

  const p = pointerPos(e);
  if (Math.hypot(p.x - ball.x, p.y - ball.y) < 56) {
    canvas.setPointerCapture(e.pointerId);
    dragging = true;
    dragStart = { x: ball.x, y: ball.y };
    dragNow = p;
    setStatus("Aim and release");
  }
}, { passive: false });

canvas.addEventListener("pointermove", e => {
  stopScroll(e);
  if (!dragging) return;
  dragNow = pointerPos(e);
}, { passive: false });

canvas.addEventListener("pointerup", e => {
  stopScroll(e);
  if (!dragging || won) return;

  const dx = dragStart.x - dragNow.x;
  const dy = dragStart.y - dragNow.y;
  const pull = Math.hypot(dx, dy);
  const power = Math.min(pull, 120);
  const scale = power / Math.max(pull, 1) * 0.13;

  ball.vx = dx * scale;
  ball.vy = dy * scale;

  strokes++;
  strokesEl.textContent = strokes;
  setStatus("Rolling");
  dragging = false;
}, { passive: false });

canvas.addEventListener("pointercancel", e => {
  stopScroll(e);
  dragging = false;
  setStatus("Ready");
}, { passive: false });

function drawCourse() {
  ctx.fillStyle = "#6fc66b";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = "#3c8b43";
  ctx.lineWidth = 34;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(75, 250);
  ctx.quadraticCurveTo(240, 130, 355, 250);
  ctx.quadraticCurveTo(500, 385, 685, 250);
  ctx.stroke();

  ctx.fillStyle = "#4ca653";
  ctx.beginPath();
  ctx.arc(145, 125, 48, 0, Math.PI * 2);
  ctx.arc(610, 380, 55, 0, Math.PI * 2);
  ctx.fill();

  drawBumpers();

  ctx.fillStyle = "#213020";
  ctx.beginPath();
  ctx.arc(hole.x, hole.y, hole.r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#f7f1d1";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(hole.x, hole.y, hole.r + 7, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = "#b57634";
  ctx.fillRect(windmill.x - 34, windmill.y - 55, 68, 110);

  ctx.fillStyle = "#f6d28a";
  ctx.beginPath();
  ctx.moveTo(windmill.x - 48, windmill.y - 55);
  ctx.lineTo(windmill.x, windmill.y - 105);
  ctx.lineTo(windmill.x + 48, windmill.y - 55);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = "#8d5d2a";
  ctx.fillRect(windmill.x - 52, windmill.y + 52, 104, 14);
}

function drawBumpers() {
  bumpers.forEach(b => {
    ctx.fillStyle = "#9f6b34";
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#d6b46c";
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r - 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#6fc66b";
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r - 18, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = "#244b2e";
  ctx.font = "800 15px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("shape it", 300, 253);
}

function drawWindmill() {
  ctx.save();
  ctx.translate(windmill.x, windmill.y);
  ctx.rotate(windmill.angle);

  for (let i = 0; i < 4; i++) {
    ctx.rotate(Math.PI / 2);
    ctx.fillStyle = "#f9f0c7";
    ctx.fillRect(-8, -windmill.r, 16, windmill.r);
    ctx.strokeStyle = "#8d5d2a";
    ctx.lineWidth = 3;
    ctx.strokeRect(-8, -windmill.r, 16, windmill.r);
  }

  ctx.fillStyle = "#5b341d";
  ctx.beginPath();
  ctx.arc(0, 0, 14, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function collideBumpers() {
  bumpers.forEach(b => {
    const dx = ball.x - b.x;
    const dy = ball.y - b.y;
    const dist = Math.hypot(dx, dy);
    const minDist = ball.r + b.r;

    if (dist < minDist && dist > 0) {
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = minDist - dist;

      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const dot = ball.vx * nx + ball.vy * ny;
      if (dot < 0) {
        ball.vx -= 1.8 * dot * nx;
        ball.vy -= 1.8 * dot * ny;
        ball.vx *= 0.86;
        ball.vy *= 0.86;
        setStatus("Bumper bounce");
      }
    }
  });
}

function triggerBladeHit(px, py) {
  hitFlash = 18;
  shake = 12;
  setStatus("BLADE HIT!", true);
  ball.vx += px * 2.2;
  ball.vy += py * 2.2;
}

function bladeCollision() {
  const dx = ball.x - windmill.x;
  const dy = ball.y - windmill.y;
  const dist = Math.hypot(dx, dy);

  if (dist > windmill.r + ball.r || dist < 18 || ballSpeed() < 0.1) return;

  for (let i = 0; i < 4; i++) {
    const a = windmill.angle + i * Math.PI / 2;
    const px = Math.cos(a);
    const py = Math.sin(a);
    const along = dx * px + dy * py;
    const side = Math.abs(dx * -py + dy * px);

    if (along > 12 && along < windmill.r && side < ball.r + 8) {
      ball.vx = -ball.vx * 0.72;
      ball.vy = -ball.vy * 0.72;
      triggerBladeHit(px, py);
      return;
    }
  }
}

function updateBall() {
  ball.x += ball.vx;
  ball.y += ball.vy;

  collideBumpers();

  ball.vx *= 0.985;
  ball.vy *= 0.985;

  if (ballStopped()) {
    ball.vx = 0;
    ball.vy = 0;
    if (!won && hitFlash <= 0) setStatus("Ready");
  }

  if (ball.x < 35 || ball.x > canvas.width - 35) ball.vx *= -0.75;
  if (ball.y < 45 || ball.y > canvas.height - 45) ball.vy *= -0.75;

  ball.x = Math.max(35, Math.min(canvas.width - 35, ball.x));
  ball.y = Math.max(45, Math.min(canvas.height - 45, ball.y));

  const dHole = Math.hypot(ball.x - hole.x, ball.y - hole.y);

  if (dHole < hole.r && ballSpeed() < 2.6 && !won) {
    won = true;
    ball.x = hole.x;
    ball.y = hole.y;
    ball.vx = 0;
    ball.vy = 0;

    if (strokes === 1) setStatus("Hole in one!");
    else if (strokes === 2) setStatus("Birdie!");
    else if (strokes === 3) setStatus("Par");
    else if (strokes === 4) setStatus("Bogey");
    else setStatus("Finished");

    showScorecard();
  }
}

function drawBall() {
  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#c9c9c9";
  ctx.lineWidth = 2;
  ctx.stroke();
}

function drawAim() {
  if (!dragging) return;

  const dx = dragStart.x - dragNow.x;
  const dy = dragStart.y - dragNow.y;
  const rawPull = Math.hypot(dx, dy);
  const pull = Math.min(rawPull, 120);
  const powerPct = pull / 120;
  const angle = Math.atan2(dy, dx);

  const endX = ball.x + Math.cos(angle) * pull * 1.45;
  const endY = ball.y + Math.sin(angle) * pull * 1.45;

  ctx.strokeStyle = "#17351dcc";
  ctx.lineWidth = 11;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(ball.x, ball.y);
  ctx.lineTo(endX, endY);
  ctx.stroke();

  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(ball.x, ball.y);
  ctx.lineTo(endX, endY);
  ctx.stroke();

  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(endX, endY, 8, 0, Math.PI * 2);
  ctx.fill();

  const meterX = 24;
  const meterY = 28;
  const meterW = 190;
  const meterH = 18;

  ctx.fillStyle = "#18331fdd";
  ctx.fillRect(meterX, meterY, meterW, meterH);

  ctx.fillStyle = powerPct < 0.45 ? "#dfffa1" : powerPct < 0.75 ? "#ffe082" : "#ff8b73";
  ctx.fillRect(meterX, meterY, meterW * powerPct, meterH);

  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 2;
  ctx.strokeRect(meterX, meterY, meterW, meterH);

  ctx.fillStyle = "#ffffff";
  ctx.font = "800 15px system-ui, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("POWER", meterX, meterY + 36);
}

function drawHitFeedback() {
  if (hitFlash <= 0) return;

  const alpha = hitFlash / 18;

  ctx.fillStyle = `rgba(255, 75, 55, ${0.18 * alpha})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, 24 + (18 - hitFlash) * 3, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
  ctx.font = "900 34px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("BLADE HIT!", canvas.width / 2, 86);
}

function loop() {
  windmill.angle += windmill.speed;

  const sx = shake > 0 ? (Math.random() - 0.5) * shake : 0;
  const sy = shake > 0 ? (Math.random() - 0.5) * shake : 0;

  ctx.save();
  ctx.translate(sx, sy);

  drawCourse();
  drawWindmill();
  bladeCollision();
  updateBall();
  drawAim();
  drawBall();
  drawHitFeedback();

  ctx.restore();

  if (hitFlash > 0) hitFlash--;
  if (shake > 0) shake *= 0.82;

  requestAnimationFrame(loop);
}

resetGame();
loop();
</script>
</body>
</html>
